require __DIR__.'/../lib/auth_teacher.php';$u=require_teacher();if($_SERVER['REQUEST_METHOD']!=='POST')exit;verify_csrf();$id=(int)($_POST['id']??0);$s=db()->prepare('SELECT storage_dir FROM games WHERE id=? AND teacher_id=?');$s->execute([$id,$u['id']]);$g=$s->fetch();if($g){$d=__DIR__.'/../storage/games/'.$g['storage_dir'];if(is_dir($d)){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($d,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f){$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());}@rmdir($d);}db()->prepare('DELETE FROM games WHERE id=? AND teacher_id=?')->execute([$id,$u['id']]);}redirect('/guru/dashboard.php?msg='.urlencode('Game dihapus.'));
